CREATE TABLE IF NOT EXISTS users (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), name TEXT NOT NULL, email TEXT NOT NULL UNIQUE, password_hash TEXT NOT NULL, role TEXT NOT NULL DEFAULT 'user' CHECK(role IN ('user','admin')), created_at TIMESTAMPTZ NOT NULL DEFAULT now());
ALTER TABLE users ADD COLUMN IF NOT EXISTS status TEXT NOT NULL DEFAULT 'active' CHECK(status IN ('active','suspended'));
CREATE TABLE IF NOT EXISTS preferences (user_id UUID PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE, diets TEXT[] NOT NULL DEFAULT '{}', exclusions TEXT[] NOT NULL DEFAULT '{}');
CREATE TABLE IF NOT EXISTS categories (id SERIAL PRIMARY KEY, name TEXT NOT NULL UNIQUE, slug TEXT NOT NULL UNIQUE, parent_id INT REFERENCES categories(id) ON DELETE SET NULL);
CREATE TABLE IF NOT EXISTS sources (id SERIAL PRIMARY KEY, name TEXT NOT NULL, url TEXT, license TEXT NOT NULL DEFAULT 'original', permission_notes TEXT);
CREATE TABLE IF NOT EXISTS recipes (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), title TEXT NOT NULL, slug TEXT NOT NULL UNIQUE, description TEXT NOT NULL, image_url TEXT, prep_minutes INT NOT NULL DEFAULT 0, cook_minutes INT NOT NULL DEFAULT 0, difficulty TEXT NOT NULL DEFAULT 'Easy', servings INT NOT NULL DEFAULT 2, cuisine TEXT, source_id INT REFERENCES sources(id) ON DELETE SET NULL, instructions TEXT[] NOT NULL DEFAULT '{}', nutrition JSONB, status TEXT NOT NULL DEFAULT 'published' CHECK(status IN ('draft','pending','published','rejected','suspended')), created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS recipe_categories (recipe_id UUID REFERENCES recipes(id) ON DELETE CASCADE, category_id INT REFERENCES categories(id) ON DELETE CASCADE, PRIMARY KEY(recipe_id,category_id));
CREATE TABLE IF NOT EXISTS ingredients (id SERIAL PRIMARY KEY, name TEXT NOT NULL UNIQUE, category TEXT NOT NULL DEFAULT 'Other', allergens TEXT[] NOT NULL DEFAULT '{}', verified BOOLEAN NOT NULL DEFAULT false, brand_flag BOOLEAN NOT NULL DEFAULT false);
CREATE TABLE IF NOT EXISTS recipe_ingredients (recipe_id UUID REFERENCES recipes(id) ON DELETE CASCADE, ingredient_id INT REFERENCES ingredients(id), quantity NUMERIC, unit TEXT NOT NULL DEFAULT '', notes TEXT, optional BOOLEAN NOT NULL DEFAULT false, PRIMARY KEY(recipe_id,ingredient_id));
CREATE TABLE IF NOT EXISTS dietary_labels (id SERIAL PRIMARY KEY, name TEXT NOT NULL UNIQUE, explanation TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS recipe_diets (recipe_id UUID REFERENCES recipes(id) ON DELETE CASCADE, diet_id INT REFERENCES dietary_labels(id) ON DELETE CASCADE, PRIMARY KEY(recipe_id,diet_id));
CREATE TABLE IF NOT EXISTS ratings (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), user_id UUID REFERENCES users(id) ON DELETE CASCADE, recipe_id UUID REFERENCES recipes(id) ON DELETE CASCADE, stars INT NOT NULL CHECK(stars BETWEEN 1 AND 5), comment TEXT, cooking_notes TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE(user_id,recipe_id));
CREATE TABLE IF NOT EXISTS reports (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), user_id UUID REFERENCES users(id) ON DELETE SET NULL, recipe_id UUID REFERENCES recipes(id) ON DELETE CASCADE, reason TEXT NOT NULL, details TEXT, status TEXT NOT NULL DEFAULT 'open', created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS favorites (user_id UUID REFERENCES users(id) ON DELETE CASCADE, recipe_id UUID REFERENCES recipes(id) ON DELETE CASCADE, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), PRIMARY KEY(user_id,recipe_id));
CREATE TABLE IF NOT EXISTS pantry_items (user_id UUID REFERENCES users(id) ON DELETE CASCADE, ingredient_id INT REFERENCES ingredients(id) ON DELETE CASCADE, quantity NUMERIC, unit TEXT, PRIMARY KEY(user_id,ingredient_id));
CREATE TABLE IF NOT EXISTS meal_plans (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), user_id UUID REFERENCES users(id) ON DELETE CASCADE, week_start DATE NOT NULL, UNIQUE(user_id,week_start));
CREATE TABLE IF NOT EXISTS meal_plan_entries (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), plan_id UUID REFERENCES meal_plans(id) ON DELETE CASCADE, recipe_id UUID REFERENCES recipes(id) ON DELETE CASCADE, day DATE NOT NULL, meal TEXT NOT NULL CHECK(meal IN ('breakfast','lunch','dinner','snack')), servings INT NOT NULL DEFAULT 2);
CREATE TABLE IF NOT EXISTS shopping_lists (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), user_id UUID REFERENCES users(id) ON DELETE CASCADE, name TEXT NOT NULL DEFAULT 'My shopping list', created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS shopping_items (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), list_id UUID REFERENCES shopping_lists(id) ON DELETE CASCADE, ingredient_id INT REFERENCES ingredients(id) ON DELETE SET NULL, name TEXT NOT NULL, quantity NUMERIC, unit TEXT, category TEXT NOT NULL DEFAULT 'Other', checked BOOLEAN NOT NULL DEFAULT false);
ALTER TABLE shopping_items ADD COLUMN IF NOT EXISTS generated_quantity NUMERIC;
CREATE TABLE IF NOT EXISTS substitution_requests (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), user_id UUID REFERENCES users(id) ON DELETE SET NULL, recipe_id UUID REFERENCES recipes(id) ON DELETE SET NULL, ingredient TEXT NOT NULL, request TEXT NOT NULL, response JSONB, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS admin_logs (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), admin_id UUID REFERENCES users(id), action TEXT NOT NULL, target_type TEXT, target_id TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS search_history (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), user_id UUID REFERENCES users(id) ON DELETE CASCADE, query TEXT NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS recipes_status_idx ON recipes(status); CREATE INDEX IF NOT EXISTS recipes_title_idx ON recipes USING GIN(to_tsvector('english', title || ' ' || description)); CREATE INDEX IF NOT EXISTS ratings_recipe_idx ON ratings(recipe_id);
